import { Country, Channel } from '../types';

const API_BASE = 'https://iptv-org.github.io/api';
const PLAYLIST_BASE = 'https://iptv-org.github.io/iptv/countries';
const CATEGORY_BASE = 'https://iptv-org.github.io/iptv/categories';
const LANGUAGE_BASE = 'https://iptv-org.github.io/iptv/languages';
const RADIO_API_BASE = 'https://de1.api.radio-browser.info/json/stations/bycountrycodeexact';

// 严格执行合规：排除受限地区
const EXCLUDED_REGIONS: string[] = ['CN', 'TW', 'HK', 'MO'];

export const GLOBAL_COUNTRY: Country = { name: '全球顶级信道', code: 'GLOBAL', languages: ['en'], flag: '🌐' };

const FALLBACK_COUNTRIES: Country[] = [
    GLOBAL_COUNTRY,
    { name: '美国', code: 'US', languages: ['en'], flag: '🇺🇸' },
    { name: '日本', code: 'JP', languages: ['ja'], flag: '🇯🇵' },
    { name: '韩国', code: 'KR', languages: ['ko'], flag: '🇰🇷' },
    { name: '英国', code: 'GB', languages: ['en'], flag: '🇬🇧' },
    { name: '法国', code: 'FR', languages: ['fr'], flag: '🇫🇷' },
    { name: '德国', code: 'DE', languages: ['de'], flag: '🇩🇪' },
    { name: '加拿大', code: 'CA', languages: ['en'], flag: '🇨🇦' },
    { name: '澳大利亚', code: 'AU', languages: ['en'], flag: '🇦🇺' },
    { name: '越南', code: 'VN', languages: ['vi'], flag: '🇻🇳' },
    { name: '新加坡', code: 'SG', languages: ['en'], flag: '🇸🇬' },
    { name: '泰国', code: 'TH', languages: ['th'], flag: '🇹🇭' },
    { name: '巴西', code: 'BR', languages: ['pt'], flag: '🇧🇷' },
    { name: '意大利', code: 'IT', languages: ['it'], flag: '🇮🇹' }
];

export const getTimezone = (countryCode: string): string => {
  const map: Record<string, string> = { 
    'US': 'America/New_York', 'JP': 'Asia/Tokyo', 'GB': 'Europe/London', 
    'KR': 'Asia/Seoul', 'FR': 'Europe/Paris', 'DE': 'Europe/Berlin'
  };
  return map[countryCode] || 'UTC';
};

export const fetchCountries = async (): Promise<Country[]> => {
  try {
    const response = await fetch(`${API_BASE}/countries.json`);
    if (!response.ok) return FALLBACK_COUNTRIES;
    const data = await response.json();
    const filtered = data
        .filter((c: Country) => !EXCLUDED_REGIONS.includes(c.code))
        .sort((a: Country, b: Country) => a.name.localeCompare(b.name));

    return filtered.length > 5 ? [GLOBAL_COUNTRY, ...filtered] : FALLBACK_COUNTRIES;
  } catch (error) { 
    return FALLBACK_COUNTRIES; 
  }
};

export const fetchChannelsByCountry = async (countryCode: string, refresh = false): Promise<Channel[]> => {
  if (EXCLUDED_REGIONS.includes(countryCode)) return [];
  if (countryCode === 'GLOBAL') return fetchGlobalTopChannels();

  try {
    const response = await fetch(`${PLAYLIST_BASE}/${countryCode.toLowerCase()}.m3u${refresh ? `?t=${Date.now()}` : ''}`);
    if (!response.ok) return [];
    const text = await response.text();
    return parseM3U(text).map(c => ({ ...c, type: 'tv' as const }));
  } catch (error) { 
    return []; 
  }
};

const fetchGlobalTopChannels = async (): Promise<Channel[]> => {
    // 聚合全球顶级新闻频道
    return [
        { id: 'abc-news', name: 'ABC News Live', logo: 'https://upload.wikimedia.org/wikipedia/commons/2/2a/ABC_News_Logo.svg', url: 'https://content.uplynk.com/channel/3324f2467c414329b3b0cc5cd987b6be.m3u8', group: 'Global News' },
        { id: 'nhk-world', name: 'NHK World-Japan', logo: 'https://upload.wikimedia.org/wikipedia/commons/7/7b/NHK_World_Logo.svg', url: 'https://nhkworld.webcdn.stream.ne.jp/www11/nhkworld-tv/global/2003458/live.m3u8', group: 'Global News' },
        { id: 'france-24', name: 'France 24 English', logo: 'https://upload.wikimedia.org/wikipedia/commons/2/20/France_24_Logo.svg', url: 'https://static.france24.com/live/F24_EN_LO_HLS/live_web.m3u8', group: 'Global News' },
        { id: 'nasa-tv', name: 'NASA TV', logo: 'https://upload.wikimedia.org/wikipedia/commons/e/e5/NASA_logo.svg', url: 'https://ntv1.akamaized.net/hls/live/2013975/NASA-NTV1-HLS/master.m3u8', group: 'Science' }
    ];
};

export const fetchRadioStations = async (countryCode: string): Promise<Channel[]> => {
  if (EXCLUDED_REGIONS.includes(countryCode) || countryCode === 'GLOBAL') return [];
  try {
    const response = await fetch(`${RADIO_API_BASE}/${countryCode}`);
    const data = await response.json();
    return data.map((s: any) => ({
      id: s.stationuuid,
      name: s.name,
      logo: s.favicon,
      url: s.url_resolved,
      group: s.tags || 'Radio',
      type: 'radio'
    }));
  } catch (e) { return []; }
};

export const fetchGlobalChannelsByCategory = async (category: string): Promise<Channel[]> => {
    const catMap: Record<string, string> = { '新闻': 'news', '体育': 'sports', '电影': 'movies', '少儿': 'kids' };
    const slug = catMap[category] || 'general';
    try {
        const response = await fetch(`${CATEGORY_BASE}/${slug}.m3u`);
        if (!response.ok) return [];
        const text = await response.text();
        return parseM3U(text).slice(0, 100);
    } catch (e) { return []; }
};

export const parseM3U = (content: string): Channel[] => {
  const lines = content.split('\n');
  const channels: Channel[] = [];
  let current: Partial<Channel> = {};
  for (let line of lines) {
    line = line.trim();
    if (line.startsWith('#EXTINF:')) {
      const name = line.substring(line.lastIndexOf(',') + 1).trim();
      const logo = line.match(/tvg-logo="([^"]*)"/)?.[1] || null;
      const group = line.match(/group-title="([^"]*)"/)?.[1] || 'Public';
      current = { name, logo, group };
    } else if (line && !line.startsWith('#')) {
      if (current.name) {
        channels.push({ ...current as Channel, id: Math.random().toString(36).substr(2, 9), url: line });
        current = {};
      }
    }
  }
  return channels;
};

import React, { useEffect, useRef, useState, useCallback } from 'react';
import Hls from 'hls.js';
import { Play, RefreshCw, Square, Star, Volume2, VolumeX, Maximize, Clock, Zap, Globe, Camera, Terminal, AlertTriangle } from 'lucide-react';
import { AppTheme, Channel, Country, Language } from '../types';

interface VideoPlayerProps {
  channel: Channel | null;
  country: Country | null; 
  theme: AppTheme;
  isFavorite: boolean;
  onToggleFavorite: () => void;
  onAutoSkip?: () => void;
  lang: Language;
}

export const VideoPlayer: React.FC<VideoPlayerProps> = ({ 
    channel, country, theme, isFavorite, onToggleFavorite, onAutoSkip, lang
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const hlsRef = useRef<Hls | null>(null);
  const [loading, setLoading] = useState(false);
  const [isPlaying, setIsPlaying] = useState(false);
  const [error, setError] = useState(false);
  const [volume, setVolume] = useState(1);
  const [isMuted, setIsMuted] = useState(false);

  const t = {
    zh: { sync: '卫星链路同步中...', fail: '信号锁定失败', retry: '强制重连', live: '实时传输' },
    en: { sync: 'Syncing Satellite...', fail: 'Signal Lock Failed', retry: 'Relink', live: 'LIVE' }
  }[lang];

  const initPlayer = useCallback(() => {
    if (!channel?.url || !videoRef.current) return;

    setError(false);
    setLoading(true);

    if (hlsRef.current) {
        hlsRef.current.destroy();
        hlsRef.current = null;
    }

    const url = channel.url;
    if (url.includes('.m3u8') && Hls.isSupported()) {
        const hls = new Hls({ enableWorker: true, lowLatencyMode: true });
        hlsRef.current = hls;
        hls.loadSource(url);
        hls.attachMedia(videoRef.current);
        hls.on(Hls.Events.MANIFEST_PARSED, () => {
            setLoading(false);
            videoRef.current?.play().catch(() => setIsPlaying(false));
            setIsPlaying(true);
        });
        hls.on(Hls.Events.ERROR, (event, data) => {
            if (data.fatal) setError(true);
        });
    } else {
        videoRef.current.src = url;
        videoRef.current.oncanplay = () => {
            setLoading(false);
            videoRef.current?.play();
            setIsPlaying(true);
        };
        videoRef.current.onerror = () => setError(true);
    }
  }, [channel]);

  useEffect(() => { initPlayer(); }, [initPlayer]);

  const { styles } = theme;

  return (
    <div className="relative w-full group overflow-hidden">
      <div className={`relative w-full aspect-video bg-black ${styles.layoutShape} overflow-hidden border ${styles.border} shadow-2xl`}>

        {/* 扫描线 Overlay */}
        <div className="absolute inset-0 pointer-events-none z-20 opacity-[0.03] bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_4px,3px_100%]"></div>

        <video ref={videoRef} className="w-full h-full object-contain" playsInline muted={isMuted} />

        {loading && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 backdrop-blur-md z-30 space-y-4">
                <RefreshCw className="w-10 h-10 text-cyan-400 animate-spin" />
                <span className="text-[10px] font-black uppercase tracking-widest text-cyan-400">{t.sync}</span>
            </div>
        )}

        {error && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/90 z-40 space-y-6">
                <AlertTriangle className="w-16 h-16 text-rose-500 animate-pulse" />
                <div className="text-center">
                    <h3 className="text-white font-black uppercase">{t.fail}</h3>
                    <button onClick={initPlayer} className="mt-4 px-6 py-2 bg-white text-black text-[10px] font-bold rounded-full hover:bg-cyan-400 transition-all">
                        {t.retry}
                    </button>
                </div>
            </div>
        )}

        {/* 悬浮控制台 */}
        <div className={`absolute inset-x-6 bottom-6 p-4 bg-black/40 backdrop-blur-3xl rounded-2xl border border-white/10 opacity-0 group-hover:opacity-100 transition-all duration-500 translate-y-4 group-hover:translate-y-0 z-50`}>
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <button onClick={() => { isPlaying ? videoRef.current?.pause() : videoRef.current?.play(); setIsPlaying(!isPlaying); }} className="w-12 h-12 bg-white text-black rounded-full flex items-center justify-center hover:scale-110 transition-transform">
                        {isPlaying ? <Square className="w-5 h-5 fill-current" /> : <Play className="w-5 h-5 fill-current ml-1" />}
                    </button>
                    <div>
                        <h4 className="text-white font-bold text-sm truncate max-w-[200px]">{channel?.name}</h4>
                        <div className="flex items-center gap-2 text-[10px] text-white/40 uppercase font-black">
                            <span className="text-rose-500 animate-pulse">{t.live}</span>
                            <span>•</span>
                            <Globe className="w-3 h-3" />
                            <span>{country?.name}</span>
                        </div>
                    </div>
                </div>
                <div className="flex items-center gap-2">
                    <button onClick={onToggleFavorite} className={`p-3 rounded-xl transition-all ${isFavorite ? 'bg-amber-400 text-black' : 'bg-white/5 text-white hover:bg-white/10'}`}>
                        <Star className={`w-4 h-4 ${isFavorite ? 'fill-current' : ''}`} />
                    </button>
                    <button onClick={() => videoRef.current?.requestFullscreen()} className="p-3 bg-white/5 text-white hover:bg-white/10 rounded-xl">
                        <Maximize className="w-4 h-4" />
                    </button>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

