  const takeScreenshot = () => {
    const video = videoRef.current;
    if (!video) return;
    try {
        const canvas = document.createElement('canvas');
        canvas.width = video.videoWidth;
        canvas.height = video.videoHeight;
        const ctx = canvas.getContext('2d');
        ctx?.drawImage(video, 0, 0, canvas.width, canvas.height);

        const link = document.createElement('a');
        link.download = `Looq-Snapshot-${channel?.name}-${Date.now()}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
        triggerToast(t.shotSuccess);
    } catch (e) {
        triggerToast(t.corsWarning);
    }
  };

  // 录屏逻辑
  const toggleRecording = () => {
    const video = videoRef.current;
    if (!video) return;

    if (isRecording) {
        mediaRecorderRef.current?.stop();
        setIsRecording(false);
    } else {
        try {
            const stream = (video as any).captureStream ? (video as any).captureStream() : (video as any).mozCaptureStream ? (video as any).mozCaptureStream() : null;
            if (!stream) throw new Error('Stream capture not supported');

            const recorder = new MediaRecorder(stream, { mimeType: 'video/webm' });
            mediaRecorderRef.current = recorder;
            chunksRef.current = [];

            recorder.ondataavailable = (e) => chunksRef.current.push(e.data);
            recorder.onstop = () => {
                const blob = new Blob(chunksRef.current, { type: 'video/webm' });
                const url = URL.createObjectURL(blob);
                const link = document.createElement('a');
                link.download = `Looq-Record-${channel?.name}-${Date.now()}.webm`;
                link.href = url;
                link.click();
                triggerToast(t.recStop);
            };

            recorder.start();
            setIsRecording(true);
            triggerToast(t.recStart);
        } catch (e) {
            triggerToast(t.corsWarning);
        }
    }
  };

  const { styles } = theme;

  return (
    <div className="relative w-full group overflow-hidden">
      <div className={`relative w-full aspect-video bg-black ${styles.layoutShape} overflow-hidden border ${styles.border} shadow-2xl`}>

        {/* 扫描线与特效 */}
        <div className="absolute inset-0 pointer-events-none z-20 opacity-[0.03] bg-[linear-gradient(rgba(18,16,16,0)_50%,rgba(0,0,0,0.25)_50%),linear-gradient(90deg,rgba(255,0,0,0.06),rgba(0,255,0,0.02),rgba(0,0,255,0.06))] bg-[length:100%_4px,3px_100%]"></div>
        {isRecording && <div className="absolute top-6 right-6 z-50 flex items-center gap-2 bg-rose-500/20 backdrop-blur-md px-3 py-1.5 rounded-full border border-rose-500/50">
            <div className="w-2 h-2 rounded-full bg-rose-500 animate-pulse"></div>
            <span className="text-[10px] font-black text-rose-500 uppercase tracking-widest">Recording</span>
        </div>}

        <video ref={videoRef} className="w-full h-full object-contain" playsInline muted={isMuted} />

        {/* Toast 提示 */}
        {showToast && (
            <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 z-[100] flex items-center gap-3 bg-black/80 backdrop-blur-2xl px-6 py-4 rounded-3xl border border-white/10 animate-in zoom-in-95 duration-300">
                <CheckCircle2 className="w-5 h-5 text-cyan-400" />
                <span className="text-sm font-bold text-white uppercase">{showToast}</span>
            </div>
        )}

        {loading && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/60 backdrop-blur-md z-30 space-y-4">
                <RefreshCw className="w-10 h-10 text-cyan-400 animate-spin" />
                <span className="text-[10px] font-black uppercase tracking-widest text-cyan-400">{t.sync}</span>
            </div>
        )}

        {error && (
            <div className="absolute inset-0 flex flex-col items-center justify-center bg-black/90 z-40 space-y-6">
                <div className="text-center">
                    <h3 className="text-white font-black uppercase">{t.fail}</h3>
                    <button onClick={initPlayer} className="mt-4 px-6 py-2 bg-white text-black text-[10px] font-bold rounded-full hover:bg-cyan-400 transition-all">
                        {t.retry}
                    </button>
                </div>
            </div>
        )}

        {/* 悬浮控制台升级版 */}
        <div className={`absolute inset-x-6 bottom-6 p-5 bg-black/40 backdrop-blur-3xl rounded-3xl border border-white/10 opacity-0 group-hover:opacity-100 transition-all duration-500 translate-y-4 group-hover:translate-y-0 z-50 shadow-2xl`}>
            <div className="flex flex-col gap-4">
                {/* 顶部：进度/信息 */}
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <h4 className="text-white font-bold text-sm truncate max-w-[200px] italic">{channel?.name}</h4>
                        <div className="flex items-center gap-2 text-[9px] text-white/40 uppercase font-black">
                            <span className="text-rose-500 animate-pulse">{t.live}</span>
                            <span>•</span>
                            <Globe className="w-3 h-3" />
                            <span>{country?.name}</span>
                        </div>
                    </div>
                    <div className="flex items-center gap-4">
                        <button onClick={takeScreenshot} title="截图" className="p-2 text-white/60 hover:text-white hover:bg-white/10 rounded-xl transition-all">
                            <Camera className="w-4 h-4" />
                        </button>
                        <button onClick={toggleRecording} title="录制" className={`p-2 rounded-xl transition-all ${isRecording ? 'text-rose-500 bg-rose-500/10' : 'text-white/60 hover:text-white hover:bg-white/10'}`}>
                            <Circle className={`w-4 h-4 ${isRecording ? 'fill-current' : ''}`} />
                        </button>
                    </div>
                </div>

                {/* 底部：控制 */}
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-6">
                        <button onClick={() => { isPlaying ? videoRef.current?.pause() : videoRef.current?.play(); setIsPlaying(!isPlaying); }} className="w-10 h-10 bg-white text-black rounded-full flex items-center justify-center hover:scale-110 transition-transform">
                            {isPlaying ? <Square className="w-4 h-4 fill-current" /> : <Play className="w-4 h-4 fill-current ml-1" />}
                        </button>

                        {/* 音量控制组 */}
                        <div className="flex items-center gap-3">
                            <button onClick={() => setIsMuted(!isMuted)} className="text-white hover:text-cyan-400 transition-colors">
                                {isMuted ? <VolumeX className="w-5 h-5" /> : volume > 0.5 ? <Volume2 className="w-5 h-5" /> : <Volume1 className="w-5 h-5" />}
                            </button>
                            <input 
                                type="range" min="0" max="1" step="0.01" 
                                value={volume} 
                                onChange={(e) => { setVolume(parseFloat(e.target.value)); setIsMuted(false); }}
                                className="w-24 h-1 bg-white/10 rounded-full appearance-none cursor-pointer accent-cyan-400 hover:accent-white transition-all"
                            />
                        </div>
                    </div>

                    <div className="flex items-center gap-2">
                        <button onClick={onToggleFavorite} className={`p-2.5 rounded-xl transition-all ${isFavorite ? 'bg-amber-400 text-black' : 'bg-white/5 text-white hover:bg-white/10'}`}>
                            <Star className={`w-4 h-4 ${isFavorite ? 'fill-current' : ''}`} />
                        </button>
                        <button onClick={() => videoRef.current?.requestFullscreen()} className="p-2.5 bg-white/5 text-white hover:bg-white/10 rounded-xl">
                            <Maximize className="w-4 h-4" />
                        </button>
                    </div>
                </div>
            </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI } from "@google/genai";
import { AppTheme, PetType, ChatMessage, Channel, Language } from '../types';
import { MessageCircle, X, Send, Bot, Cat, Dog, Rabbit, Sparkles, Wand2, Minus } from 'lucide-react';

interface AiChatPetProps {
  theme: AppTheme;
  currentChannels: Channel[];
  onSelectChannel: (channel: Channel) => void;
  lang: Language;
}

const TRANSLATIONS = {
  zh: {
    title: '智聊终端',
    changePartner: '更换伙伴',
    choosePartner: '挑选伙伴',
    partnerDesc: '它们会陪你聊天并推荐频道',
    placeholder: '输入心情...',
    recommend: '点击获取推荐',
    recommendPrompt: '有什么好频道推荐吗？',
    cat: '小猫', dog: '小狗', bunny: '兔子', robot: '助手',
    fallback: '正在同步卫星信号...',
    minimize: '最小化'
  },
  en: {
    title: 'AI Link',
    changePartner: 'Switch',
    choosePartner: 'Pick Buddy',
    partnerDesc: 'They suggest channels based on mood',
    placeholder: 'Type here...',
    recommend: 'Get Suggestion',
    recommendPrompt: 'Any channel recommendations?',
    cat: 'Cat', dog: 'Dog', bunny: 'Bunny', robot: 'Bot',
    fallback: 'Syncing satellite...',
    minimize: 'Minimize'
  }
};

export const AiChatPet: React.FC<AiChatPetProps> = ({ theme, currentChannels, onSelectChannel, lang }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [petType, setPetType] = useState<PetType>(() => (localStorage.getItem('ai_pet_type') as PetType) || null);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [inputText, setInputText] = useState('');
  const [loading, setLoading] = useState(false);
  const [showInvite, setShowInvite] = useState(false);

  const scrollRef = useRef<HTMLDivElement>(null);
  const { styles } = theme;
  const t = TRANSLATIONS[lang];

  useEffect(() => { 
      if (petType) {
          localStorage.setItem('ai_pet_type', petType);
          const timer = setTimeout(() => setShowInvite(true), 3000);
          return () => clearTimeout(timer);
      }
  }, [petType]);

  useEffect(() => { if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight; }, [messages, isExpanded]);

  const handleSend = async (forcedText?: string) => {
    const text = forcedText || inputText;
    if (!text.trim() || !petType) return;

    setShowInvite(false);
    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', text };
    setMessages(prev => [...prev, userMsg]);
    setInputText('');
    setLoading(true);

    try {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        let systemInstruction = `You are a virtual TV companion (${petType}) responding in ${lang === 'zh' ? 'Chinese' : 'English'}.
        Available channels: ${currentChannels.slice(0, 50).map(c => c.name).join(', ')}.
        Task: Chat with user and recommend channels based on mood using [[Channel Name]] format.
        Personality: ${petType === 'cat' ? '傲娇，爱吐槽，说话带点猫叫声' : petType === 'dog' ? '热情外向，忠诚，喜欢称呼用户为主人' : petType === 'bunny' ? '害羞腼腆，说话简短温柔' : '专业、客观的 AI 助手'}.`;

        const response = await ai.models.generateContent({
          model: 'gemini-3-flash-preview',
          contents: userMsg.text,
          config: { systemInstruction }
        });

        const responseText = response.text;
        const match = responseText?.match(/\[\[(.*?)\]\]/);

        if (match) {
            const recommendedName = match[1];
            const channel = currentChannels.find(c => c.name.toLowerCase().includes(recommendedName.toLowerCase()));
            if (channel) {
                setMessages(prev => [...prev, {
                    id: Date.now().toString(),
                    role: 'model',
                    text: responseText.replace(/\[\[.*?\]\]/g, channel.name) + (lang === 'zh' ? " (已为你跳转)" : " (Switched)")
                }]);
                onSelectChannel(channel);
                setLoading(false);
                return;
            }
        }

        setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: responseText || t.fallback }]);
    } catch (e) {
        setMessages(prev => [...prev, { id: Date.now().toString(), role: 'model', text: t.fallback }]);
    } finally {
        setLoading(false);
    }
  };

  const getPetIcon = (type: PetType, className: string) => {
      switch (type) {
          case 'cat': return <Cat className={className} />;
          case 'dog': return <Dog className={className} />;
          case 'bunny': return <Rabbit className={className} />;
          case 'robot': return <Bot className={className} />;
          default: return <MessageCircle className={className} />;
      }
  };

  return (
    <div className="flex flex-col items-end gap-4 pointer-events-none">
        {/* 展开后的聊天窗口 */}
        {isExpanded && (
            <div className={`
                w-80 h-[480px] flex flex-col ${styles.card} ${styles.layoutShape} overflow-hidden border ${styles.border} 
                shadow-3xl transition-all duration-500 pointer-events-auto
                animate-in slide-in-from-bottom-6 fade-in-0 duration-300 relative
            `}>
                {showInvite && !loading && (
                    <div onClick={() => handleSend(t.recommendPrompt)} className="absolute top-[65px] left-4 right-4 z-20 bg-cyan-500 text-black p-3 rounded-2xl shadow-2xl cursor-pointer animate-in slide-in-from-top-4 duration-500 hover:scale-105 transition-transform">
                        <div className="flex items-center gap-3">
                            <span className="text-[10px] font-black uppercase tracking-widest flex items-center gap-2"><Wand2 className="w-4 h-4" /> {t.recommend}</span>
                        </div>
                    </div>
                )}

                <div className={`p-4 flex items-center justify-between border-b ${styles.border} shrink-0 bg-black/20`}>
                     <div className={`flex items-center gap-2.5 ${styles.textMain} font-black uppercase tracking-widest text-[10px]`}>
                         <Sparkles className="w-3.5 h-3.5 text-yellow-400" />
                         <span>{t.title}</span>
                     </div>
                     <div className="flex items-center gap-2">
                        {petType && (
                            <button onClick={() => { setPetType(null); setMessages([]); }} className={`text-[8px] font-black ${styles.textDim} hover:${styles.textMain} uppercase`}>
                                {t.changePartner}
                            </button>
                        )}
                        <button onClick={() => setIsExpanded(false)} className={`p-1.5 rounded-lg hover:bg-white/10 ${styles.textDim}`}>
                            <Minus className="w-4 h-4" />
                        </button>
                     </div>
                </div>

                <div className={`flex-1 overflow-y-auto p-4 space-y-4 scrollbar-thin`} ref={scrollRef}>
                    {!petType ? (
                        <div className="h-full flex flex-col items-center justify-center text-center space-y-6">
                            <div className="space-y-1">
                                <p className={`${styles.textMain} font-black text-[10px] uppercase`}>{t.choosePartner}</p>
                                <p className={`${styles.textDim} text-[8px] uppercase tracking-widest opacity-40`}>{t.partnerDesc}</p>
                            </div>
                            <div className="grid grid-cols-2 gap-2 w-full">
                                {(['cat', 'dog', 'bunny', 'robot'] as const).map(type => (
                                    <button key={type} onClick={() => { setPetType(type); setMessages([{ id: 'init', role: 'model', text: lang === 'zh' ? `哈啰！我是${TRANSLATIONS.zh[type]}伙伴。` : `Hi! I'm your ${TRANSLATIONS.en[type]}.` }]); }} className={`flex flex-col items-center gap-2 p-3 ${styles.button} ${styles.layoutShape} border ${styles.border} transition-all hover:scale-105 active:scale-95 group`}>
                                        {getPetIcon(type, "w-6 h-6 group-hover:rotate-6 transition-transform")}
                                        <span className="text-[8px] font-black uppercase tracking-widest">{t[type]}</span>
                                    </button>
                                ))}
                            </div>
                        </div>
                    ) : (
                        <div className="space-y-4">
                            {messages.map(msg => (
                                <div key={msg.id} className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}>
                                    <div className={`max-w-[90%] px-3.5 py-2 ${styles.layoutShape} text-[11px] font-bold leading-relaxed shadow-sm ${msg.role === 'user' ? `${styles.buttonPrimary} rounded-tr-none` : `${styles.card} rounded-tl-none border ${styles.border}`}`}>
                                        {msg.text}
                                    </div>
                                </div>
                            ))}
                            {loading && (
                                <div className="flex justify-start">
                                     <div className={`${styles.card} px-3 py-2 ${styles.layoutShape} rounded-tl-none animate-pulse border ${styles.border}`}>
                                         <div className="flex gap-1.5 text-cyan-500">
                                             <div className="w-1 h-1 bg-current rounded-full animate-bounce"></div>
                                             <div className="w-1 h-1 bg-current rounded-full animate-bounce delay-150"></div>
                                             <div className="w-1 h-1 bg-current rounded-full animate-bounce delay-300"></div>
                                         </div>
                                     </div>
                                </div>
                            )}
                        </div>
                    )}
                </div>

                {petType && (
                    <div className={`p-4 border-t ${styles.border} flex items-center gap-2 bg-black/5 shrink-0`}>
                        <input 
                            type="text" 
                            value={inputText}
                            onChange={(e) => setInputText(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
                            placeholder={t.placeholder}
                            className={`flex-1 ${styles.input} ${styles.layoutShape} px-4 py-2 text-[10px] focus:outline-none font-bold placeholder:opacity-40`}
                        />
                        <button onClick={() => handleSend()} disabled={!inputText.trim() || loading} className={`p-2.5 ${styles.layoutShape} ${styles.buttonPrimary} disabled:opacity-30 shadow-lg`}>
                            <Send className="w-3 h-3" />
                        </button>
                    </div>
                )}
            </div>
        )}

        {/* 悬浮球 (Minimized State) */}
        <button 
            onClick={() => setIsExpanded(!isExpanded)}
            className={`
                pointer-events-auto w-14 h-14 rounded-full flex items-center justify-center 
                ${isExpanded ? 'bg-white text-black scale-0 opacity-0' : `${styles.buttonPrimary} shadow-[0_0_30px_rgba(6,182,212,0.3)] hover:scale-110 active:scale-95`}
                transition-all duration-500 border-2 border-white/20 relative group
            `}
        >
            {getPetIcon(petType, "w-6 h-6")}
            {!isExpanded && loading && (
                <span className="absolute inset-0 rounded-full border-2 border-white border-t-transparent animate-spin"></span>
            )}
            {!isExpanded && !loading && (
                <span className="absolute -top-1 -right-1 flex h-3 w-3">
                    <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-cyan-400 opacity-75"></span>
                    <span className="relative inline-flex rounded-full h-3 w-3 bg-cyan-500"></span>
                </span>
            )}

            {/* Tooltip */}
            {!isExpanded && (
                <div className="absolute right-full mr-4 px-3 py-1.5 bg-black/80 backdrop-blur-md rounded-xl border border-white/10 opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none whitespace-nowrap">
                    <span className="text-[9px] font-black uppercase tracking-widest text-white">{t.title}</span>
                </div>
            )}
        </button>
    </div>
  );
};

