                <button onClick={() => setSidebarOpen(true)} className="md:hidden p-2 text-white"><Menu /></button>
                <div className="flex items-center gap-3">
                    <span className="text-3xl">{selectedCountry?.flag}</span>
                    <h1 className={`text-xl font-black uppercase tracking-tighter ${theme.styles.textMain}`}>
                        {discoveryTag || selectedCountry?.name}
                    </h1>
                </div>
            </div>
            <div className="flex items-center gap-4">
                <button onClick={() => setLang(lang === 'zh' ? 'en' : 'zh')} className="text-[10px] font-black text-white/40 uppercase">
                    {lang === 'zh' ? 'EN' : '中文'}
                </button>
                <button onClick={() => loadChannels()} className={`p-2 rounded-lg ${theme.styles.button} ${loading ? 'animate-spin' : ''}`}>
                    <RefreshCw className="w-4 h-4" />
                </button>
            </div>
        </header>

        <div className="flex-1 overflow-y-auto p-8 scrollbar-thin">
            <div className="max-w-6xl mx-auto space-y-12">
                <section>
                    <VideoPlayer 
                        channel={currentChannel} country={selectedCountry} theme={theme}
                        isFavorite={!!currentChannel && favorites.some(f => f.id === currentChannel.id)}
                        onToggleFavorite={() => currentChannel && toggleFavorite(currentChannel)}
                        lang={lang}
                    />
                    <FavoritesBar favorites={favorites} currentChannel={currentChannel} onSelectChannel={setCurrentChannel} theme={theme} mode={mode} />
