  const [isMuted, setIsMuted] = useState(false);
  const [isRecording, setIsRecording] = useState(false);
  const [toast, setToast] = useState<string | null>(null);

  const t = {
    zh: { 
        sync: '链路同步中...', fail: '信号锁定失败', retry: '重制连接', live: 'LIVE',
        snap: '快照已保存', recStart: '录制已开始', recEnd: '录像已导出', error: '系统异常'
    },
    en: { 
        sync: 'Syncing...', fail: 'No Signal', retry: 'Relink', live: 'LIVE',
        snap: 'Snapshot Saved', recStart: 'Recording...', recEnd: 'Video Saved', error: 'System Error'
    }
  }[lang];

  const initPlayer = useCallback(() => {
    if (!channel?.url || !videoRef.current) return;
    setError(false); 
    setLoading(true);

    try {
        if (hlsRef.current) {
            hlsRef.current.destroy();
            hlsRef.current = null;
        }

        const url = channel.url;
        if (url.toLowerCase().includes('.m3u8') && Hls.isSupported()) {
            const hls = new Hls({
                enableWorker: true,
                lowLatencyMode: true,
                backBufferLength: 60
            });
            hlsRef.current = hls;
            hls.loadSource(url);
            hls.attachMedia(videoRef.current);
            hls.on(Hls.Events.MANIFEST_PARSED, () => {
                setLoading(false);
                videoRef.current?.play().catch(() => setIsPlaying(false));
                setIsPlaying(true);
            });
            hls.on(Hls.Events.ERROR, (_, data) => {
                if (data.fatal) {
                    setError(true);
                    setLoading(false);
                }
            });
        } else {
            videoRef.current.crossOrigin = "anonymous";
            videoRef.current.src = url;
            videoRef.current.oncanplay = () => {
                setLoading(false);
                videoRef.current?.play().catch(() => setIsPlaying(false));
                setIsPlaying(true);
            };
            videoRef.current.onerror = () => {
                setError(true);
