      try {
        ctx.drawImage(videoRef.current, 0, 0, canvas.width, canvas.height);
        const link = document.createElement('a');
        link.download = `Looq_Snap_${channel?.name || 'TV'}.png`;
        link.href = canvas.toDataURL('image/png');
        link.click();
        showToast(t.snap);
